(()=>{'use strict';
const V='20260728-player-tabs-shell-logos-v1';
const overlay=document.getElementById('cff-public-overlay'),sidebar=document.getElementById('cff-public-sidebar'),nav=document.getElementById('cff-public-sidebar-nav'),openBtn=document.getElementById('cff-public-menu-open'),closeBtn=document.getElementById('cff-public-menu-close');
const menu=`<a href="index.html">INÍCIO</a><a href="index.html#mercado">MERCADO DA BALA</a><details open><summary>WB 2026 S2</summary><div><a href="index.html#ffws-br-s2-classificatoria">CLASSIFICATÓRIA</a><a href="index.html#ffws-br-s2-segunda-fase">SEGUNDA FASE</a><a href="index.html#ffws-br-s2-final">FINAL</a><a href="index.html#ffws-br-s2-mvp">RANKING MVP</a><a href="index.html#ffws-br-s2-equipes">EQUIPES</a><a href="index.html#ffws-br-s2-datas">DATAS</a><a href="index.html#ffws-br-s2-selecoes">SELEÇÕES DA SEASON</a><a href="index.html#ffws-br-s2-stats">ESTATÍSTICAS GERAIS</a></div></details><details><summary>EWC 2026</summary><div><a href="index.html#ewc-grupos">FASE DE GRUPOS</a><a href="index.html#ewc-repescagem">REPESCAGEM</a><a href="index.html#ewc-final">FINAL</a><a href="index.html#ewc-mvp">RANKING MVP</a><a href="index.html#ewc-equipes">EQUIPES</a><a href="index.html#ewc-stats">ESTATÍSTICAS GERAIS</a></div></details><details><summary>WB 2026 S1</summary><div><a href="index.html#tabela">CLASSIFICATÓRIA</a><a href="index.html#final">FINAL</a><a href="index.html#mvp">RANKING MVP</a><a href="index.html#equipes">EQUIPES</a><a href="index.html#datas">DATAS</a><a href="index.html#selecao-da-semana">SELEÇÕES DA SEASON</a><a href="index.html#stats">ESTATÍSTICAS GERAIS</a></div></details><details><summary>LAFF 2026 S1</summary><div><a href="index.html#laff-classificatoria">CLASSIFICATÓRIA</a><a href="index.html#laff-mvp">RANKING MVP</a><a href="index.html#laff-equipes">EQUIPES</a><a href="index.html#laff-datas">DATAS</a></div></details><details><summary>INTERNACIONAL</summary><div><a href="index.html#ffws-sea-2026-s1">FFWS SEA 2026 S1</a><a href="index.html#ffws-latam-s1">FFWS LATAM S1</a></div></details><details><summary>HISTÓRICO</summary><div><a href="index.html#hall-da-fama">HALL DA FAMA</a><a href="index.html#outros-torneios">OUTROS TORNEIOS</a><a href="index.html#outras-equipes">OUTRAS EQUIPES</a></div></details>`;
let built=false;function build(){if(!built&&nav){nav.innerHTML=menu;built=true}}function open(){build();overlay?.classList.add('is-open');sidebar?.classList.add('is-open');document.body.classList.add('cff-public-menu-open');closeBtn?.focus()}function close(){overlay?.classList.remove('is-open');sidebar?.classList.remove('is-open');document.body.classList.remove('cff-public-menu-open')}openBtn?.addEventListener('click',open);closeBtn?.addEventListener('click',close);overlay?.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
const input=document.getElementById('cff-public-search-input'),results=document.getElementById('cff-public-search-results'),submit=document.getElementById('cff-public-search-submit');let items=[],loading=null,timer=0;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
function load(){if(items.length)return Promise.resolve(items);if(loading)return loading;loading=fetch(`search-index-lite.json?v=${V}`,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{items=(d.items||[]).filter(x=>x&&x.title&&x.title!=='#N/A').map(x=>({...x,_q:norm([x.title,x.sub,...(x.aliases||[])].join(' ')),_t:norm(x.title)}));return items}).catch(()=>[]);return loading}
function url(x){if(x.type==='player')return`jogador.html?id=${encodeURIComponent(x.id)}`;if(x.type==='team')return`equipe.html?time=${encodeURIComponent(x.id)}`;return`index.html#${encodeURIComponent(x.id||'home')}`}
function score(x,q,tokens){if(x._t===q)return 1000;if(x._t.startsWith(q))return 850;if(x._q.startsWith(q))return 760;if(x._q.includes(q))return 620;let n=0;for(const t of tokens)if(x._q.includes(t))n++;return n===tokens.length?420+n*10:-1}
function render(q){q=norm(q);if(!results)return;if(!q){results.classList.remove('is-open');results.innerHTML='';return}const tokens=q.split(' ').filter(Boolean),found=items.map(x=>({x,s:score(x,q,tokens)})).filter(v=>v.s>=0).sort((a,b)=>b.s-a.s||a.x.title.localeCompare(b.x.title,'pt-BR')).slice(0,10).map(v=>v.x);results.innerHTML=found.length?found.map(x=>`<a class="cff-public-search-item" href="${url(x)}"><img src="${esc(x.image||'central free fire.webp')}" alt="" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'"><span class="cff-public-search-copy"><strong>${esc(x.title)}</strong><small>${esc(x.sub||'')}</small></span></a>`).join(''):'<div class="cff-public-search-empty">Nenhum resultado encontrado.</div>';results.classList.add('is-open')}
function requestRender(){clearTimeout(timer);timer=setTimeout(async()=>{await load();render(input?.value)},45)}input?.addEventListener('focus',()=>{load();if(input.value)requestRender()});input?.addEventListener('input',requestRender);input?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=results?.querySelector('a');if(first)location.href=first.href;else location.href=`index.html#busca-global?q=${encodeURIComponent(input.value)}`}});submit?.addEventListener('click',()=>{input?.focus();requestRender()});document.addEventListener('click',e=>{if(!e.target.closest('.cff-public-search'))results?.classList.remove('is-open')});
})();